// Run a tiny query over records and return the 0-based indices of the
// selected records, in result order.
// Each record is a list of (field, value) pairs; if a field appears more
// than once in a record, its first value counts. The query is a sequence
// of tokens separated by whitespace (leading and trailing whitespace is
// allowed). Its grammar, where every part is optional but the parts must
// come in this order:
//     [COND {"and" COND}] ["order" "by" FIELD ["desc"]] ["limit" N]
// COND is exactly three tokens FIELD OP INT, where OP is one of
// = != < <= > >=. FIELD is one or more of the characters a-z and _, and is
// not one of the keywords and, order, by, desc, limit. INT is an optional
// "-" followed by 1 to 9 digits; N is 1 to 9 digits with no sign.
// A record is selected if it satisfies every COND; a COND on a field the
// record does not have is false, for every OP including !=. With no COND,
// every record is selected. "order by FIELD" sorts the selected records
// by that field ascending ("desc": descending); records lacking the field
// come after all records that have it; records with equal values, and
// records lacking the field, keep their original relative order. Without
// "order by", the original order is kept. "limit N" keeps the first N.
// If the query does not match the grammar, return None.
// Examples:
//   run_query([[("age", 30)], [("age", 20)], [("id", 1)]], "age >= 20 order by age") == Some([1, 0])
//   run_query([[("a", 1)], [("a", 2), ("a", 9)], [("a", 3)]], "order by a desc limit 2") == Some([2, 1])
fn run_query(records: List[List[(Str, Int)]], query: Str) -> Option[List[Int]] {
  let ops = ["=", "!=", "<", "<=", ">", ">="];
  let toks = split_ws(query);
  let n = len(toks);
  let mut i = 0;
  let mut conds: List[(Str, Str, Int)] = [];
  if i < n && toks[i] != "order" && toks[i] != "limit" {
    while true {
      if i + 3 > n || !query_is_field(toks[i]) || !contains(ops, toks[i + 1]) {
        return None;
      }
      let v = toks[i + 2];
      let digits = if starts_with(v, "-") { substr(v, 1, str_len(v)) } else { v };
      if !query_is_digits(digits) {
        return None;
      }
      conds = push(conds, (toks[i], toks[i + 1], parse_int(v)?));
      i = i + 3;
      if i < n && toks[i] == "and" {
        i = i + 1;
      } else {
        break;
      }
    }
  }
  let mut order: Option[Str] = None;
  let mut desc = false;
  let mut limit = -1;
  if i < n && toks[i] == "order" {
    if i + 2 >= n || toks[i + 1] != "by" || !query_is_field(toks[i + 2]) {
      return None;
    }
    order = Some(toks[i + 2]);
    i = i + 3;
    if i < n && toks[i] == "desc" {
      desc = true;
      i = i + 1;
    }
  }
  if i < n && toks[i] == "limit" {
    if i + 1 >= n || !query_is_digits(toks[i + 1]) {
      return None;
    }
    limit = parse_int(toks[i + 1])?;
    i = i + 2;
  }
  if i != n {
    return None;
  }
  let mut sel = filter(range(0, len(records)), |j| all(conds, |c| match query_lookup(records[j], c.0) {
    Some(v) => query_holds(v, c.1, c.2),
    None => false,
  }));
  match order {
    Some(f) => {
      let have = filter(sel, |j| is_some(query_lookup(records[j], f)));
      let missing = filter(sel, |j| is_none(query_lookup(records[j], f)));
      let descending = desc;
      // sort_by is stable, so equal values keep their original order
      let sorted = sort_by(have, |j| {
        let v = unwrap_or(query_lookup(records[j], f), 0);
        if descending { 0 - v } else { v }
      });
      sel = sorted ++ missing;
    },
    None => (),
  }
  if limit >= 0 {
    sel = take(sel, limit);
  }
  Some(sel)
}

fn query_is_field(t: Str) -> Bool {
  t != "" && !contains(["and", "order", "by", "desc", "limit"], t) && all(chars(t), |c| c == "_" || is_lower(c))
}

fn query_is_digits(t: Str) -> Bool {
  let n = str_len(t);
  n >= 1 && n <= 9 && all(chars(t), |c| is_digit(c))
}

fn query_lookup(rec: List[(Str, Int)], field: Str) -> Option[Int] {
  option_map(head(filter(rec, |p| p.0 == field)), |p| p.1)
}

fn query_holds(v: Int, op: Str, x: Int) -> Bool {
  match op {
    "=" => v == x,
    "!=" => v != x,
    "<" => v < x,
    "<=" => v <= x,
    ">" => v > x,
    _ => v >= x,
  }
}
